    "visits": {
      "title": "زياراتك، أسبوعًا بأسبوع",
      "sub": "ما يحدث في كل زيارة، وما هو قرارك",
      "lead": "هذا هو الجدول المعتاد في الولايات المتحدة. قد يختلف جدولك: يضيف طبيب الأسرة أو طبيب التوليد أو القابلة زيارات وفحوصات عندما تحتاجينها.",
      "afterBirth": "بعد الولادة",
      "yourChoice": "قرارك",
      "first": {
        "when": "نحو 8–10 أسابيع",
        "title": "الزيارة الأولى",
        "i1": "يُحدَّد موعد ولادتك من آخر دورة شهرية، وغالبًا مع تصوير مبكر بالموجات فوق الصوتية.",
        "i2": "تحاليل دم: فصيلة الدم وRh، تعداد الدم، المناعة ضد الحصبة الألمانية وجدري الماء، التهاب الكبد B وC، فيروس نقص المناعة والزهري. تحليل بول، وفحوص للكلاميديا والسيلان.",
        "i3": "فحص سكر مبكر إذا كان لديك سكري في حمل سابق أو عوامل خطر أخرى.",
        "i4": "إذا كان خطر تسمم الحمل لديك أعلى، فإن الأسبرين بجرعة منخفضة (81 mg يوميًا) من الأسبوع 12 يقلل هذا الخطر. اسألي إن كان مناسبًا لك."
      },
      "genetic": {
        "when": "من الأسبوع 10",
        "title": "فحوص للطفل",
        "i1": "تحليل دم من الأسبوع 10 (الحمض النووي الحر) يكشف متلازمة داون وبعض الحالات الأخرى. الفحص الكاشف ليس تشخيصًا: النتيجة الإيجابية تعني أنه سيُعرض عليك فحص تشخيصي.",
        "i2": "فحص الحاملين يتحقق مما إذا كنتِ تحملين جينات لحالات مثل التليّف الكيسي أو ضمور العضلات الشوكي.",
        "i3": "يمكنك إجراء هذه الفحوص كلها أو بعضها أو لا شيء منها."
      },
      "monthly": {
        "when": "كل 4 أسابيع، حتى الأسبوع 28",
        "title": "زيارات منتظمة",
        "i1": "ضغط الدم والوزن والبول ونبض قلب الطفل. ومن نحو الأسبوع 20، يُقاس حجم بطنك أيضًا."
      },
      "anatomy": {
        "when": "18–22 أسبوعًا",
        "title": "تصوير تشريحي بالموجات فوق الصوتية",
        "i1": "فحص مفصّل لجسم الطفل ونموه والمشيمة. يمكنك عادةً معرفة الجنس إن أردتِ."
      },
      "sugar": {
        "when": "24–28 أسبوعًا",
        "title": "فحص السكر وتحاليل الدم",
        "i1": "مشروب حلو، ثم تحليل دم بعد ساعة، للكشف عن سكري الحمل.",
        "i2": "تعداد دم للكشف عن فقر الدم، وإعادة فحص الزهري.",
        "i3": "إذا كانت فصيلة دمك Rh سالبة: حقنة Rh (RhoGAM) في نحو الأسبوع 28."
      },
      "tdap": {
        "when": "27–36 أسبوعًا",
        "title": "لقاح السعال الديكي (Tdap)",
        "i1": "تنتقل أجسامك المضادة إلى الطفل وتحميه في الأشهر الأولى، قبل أن يتمكن من أخذ لقاحاته. يُعطى في كل حمل."
      },
      "twoweekly": {
        "when": "كل أسبوعين، من الأسبوع 28",
        "title": "الزيارات تتقارب",
        "i1": "تعرّفي على الطريقة التي يتحرك بها طفلك عادةً. عدّ الركلات اختياري. إذا تحرّك الطفل أقل من المعتاد، اتصلي في اليوم نفسه. لا تنتظري الزيارة التالية.",
        "i2": "إذا كانت لديك حالة مثل ارتفاع ضغط الدم أو السكري، فإن الفحوص الإضافية للطفل (اختبارات عدم الإجهاد أو الموجات فوق الصوتية) تبدأ غالبًا نحو الأسبوع 32."
      },
      "rsv": {
        "when": "32–36 أسبوعًا، من سبتمبر إلى يناير",
        "title": "الحماية من الفيروس المخلوي التنفسي (RSV) للطفل",
        "i1": "إما لقاح RSV لكِ بين الأسبوعين 32 و36، أو حقنة أجسام مضادة للطفل بعد الولادة. واحد منهما فقط، لا الاثنان. كلاهما يقلل احتمال دخول الطفل المستشفى بسبب RSV في شتائه الأول."
      },
      "gbs": {
        "when": "36–37 أسبوعًا",
        "title": "مسحة المكورات العقدية من المجموعة B، ووضعية الطفل",
        "i1": "مسحة من المهبل والمستقيم. نحو 1 من كل 4 نساء تحمل GBS، وهي لا تؤذيك. إذا كانت نتيجتك إيجابية، تأخذين مضادات حيوية في الوريد أثناء المخاض لحماية الطفل.",
        "i2": "التأكد من أن رأس الطفل إلى الأسفل. إذا كان الطفل في وضع مقعدي، قد يُعرض عليك قلب الطفل (التحويل الخارجي)، أو يمكنك التخطيط لولادة قيصرية.",
        "i3": "راجعي خطة ولادتك: تخفيف الألم، ومن سيكون معك، والرضاعة."
      },
      "weekly": {
        "when": "كل أسبوع، من الأسبوع 36",
        "title": "الأسابيع الأخيرة",
        "i1": "من الأسبوع 38 قد يُعرض عليك تقشير الأغشية: مسح بالإصبع عند عنق الرحم قد يساعد على بدء المخاض.",
        "i2": "يمكن عرض تحريض الولادة من الأسبوع 39. وعند الأسبوع 41 يُنصح به، لأن الخطر على الطفل يبدأ في الارتفاع."
      },
      "ppBp": {
        "when": "3–10 أيام بعد الولادة",
        "title": "فحص ضغط الدم، إذا كان مرتفعًا",
        "i1": "إذا كان لديك ارتفاع في ضغط الدم أو تسمم حمل، افحصي الضغط خلال 3 إلى 10 أيام بعد الولادة. قد يبدأ تسمم الحمل أو يسوء بعد الولادة."
      },
      "pp3": {
        "when": "خلال 3 أسابيع من الولادة",
        "title": "أول متابعة",
        "i1": "تحدّثي مع طبيب الأسرة أو طبيب التوليد أو القابلة عن النزيف والألم والرضاعة والمزاج والنوم. قد تكفي مكالمة هاتفية أو مرئية."
      },
      "ppFull": {
        "when": "خلال 12 أسبوعًا بعد الولادة، غالبًا عند 4–6 أسابيع",
        "title": "زيارة ما بعد الولادة الكاملة",
        "i1": "فحص المزاج، ووسائل منع الحمل، وكيف تتعافين، وأي خطط لحمل قادم.",
        "i2": "إذا كان لديك سكري الحمل: فحص سكر بعد 4 إلى 12 أسبوعًا من الولادة. يبقى خطر السكري من النوع 2 أعلى مدى الحياة، فاطلبي فحصًا كل 1 إلى 3 سنوات.",
        "i3": "إذا كان يتسرب منك البول أو البراز، أو تشعرين بألم أثناء الجماع، أو بانتفاخ في المهبل، اسألي عن العلاج الطبيعي لقاع الحوض. إنه يساعد. لستِ مضطرة للعيش مع ذلك."
      }
    }
